head.script:
scwin.trigger1_onclick = function(e) {
    WebSquare.wUnit.getObjById('gridView1').changeCurrency("col1", "euro");
    WebSquare.wUnit.getObjById('gridView1').changeCurrency("col2", "number");
    WebSquare.wUnit.getObjById('gridView1').changeCurrency("col3", "rupee");
    WebSquare.wUnit.getObjById('gridView1').changeCurrency("col4", "tenge");
};
scwin.trigger2_onclick = function(e) {
    WebSquare.wUnit.getObjById('gridView2').changeCurrency("col1", "euro", "#.###,00");
    WebSquare.wUnit.getObjById('gridView2').changeCurrency("col2", "number", "#,###.00");
    WebSquare.wUnit.getObjById('gridView2').changeCurrency("col3", "rupee", "##,##,###.00");
    WebSquare.wUnit.getObjById('gridView2').changeCurrency("col4", "tenge", "# ###-00");
};
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플 실행 후 'changeCurrency1'와 'changeCurrency2 API'를 클릭한다.
    //1. After running the sample, click 'changeCurrency1' and 'changeCurrency2 API'.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 상단 gridView의 formatter 설정된 값과 하단 gridView의 API를 적용한 Formatter 설정된 값으로 동일하게 변경되어진다.
    //1. It is changed to the set value of the formatter of the upper gridView and the set value of the formatter applying the API of the lower gridView.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').innerText == '111.111.111,00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').innerText == '222,222,222.00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').innerText == '33,33,33,333.00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_3').innerText == '444 444 444-00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_0').innerText == '111.111.111,00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText == '222,222,222.00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_2').innerText == '33,33,33,333.00'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_3').innerText == '444 444 444-00'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'changeCurrency2 API'를 클릭한 grdiView에서(하단) edit모두로 값을 변경한다.
    //2. Change the value from grdiView by clicking on 'changeCurrency2 API' to (bottom) edit all.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView2_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_'+$p.id+'gridView2__col2').value = '12312312'");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 2. 변경된 값의 동일한 formatter로 적용되어 보여진다.
    //2. The changed values ​​are applied to the same formatter.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText == '12,312,312.00'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
